public static class Json {
 public static readonly JsonSerializerSettings Settings=new(){TypeNameHandling=TypeNameHandling.None,MissingMemberHandling=MissingMemberHandling.Error,DateParseHandling=DateParseHandling.DateTime,MaxDepth=32,FloatParseHandling=FloatParseHandling.Double};
 public static string Write(object value)=>JsonConvert.SerializeObject(value,Formatting.Indented,Settings);
 public static T Read<T>(string text){if(Encoding.UTF8.GetByteCount(text)>2*1024*1024)throw new CadException("PAYLOAD_TOO_LARGE","Payload exceeds 2 MB.");try{using var sr=new StringReader(text);using var jr=new JsonTextReader(sr){MaxDepth=32,DateParseHandling=DateParseHandling.None};var token=JToken.Load(jr,new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error});if(jr.Read())throw new JsonException("Trailing JSON");return token.ToObject<T>(JsonSerializer.Create(Settings))??throw new JsonException("Empty payload");}catch(JsonException e){throw new CadException("INVALID_JSON",e.Message);} }
 public static string Canonical(object value){JToken Sort(JToken t)=>t is JObject o?new JObject(System.Linq.Enumerable.Select(System.Linq.Enumerable.OrderBy(o.Properties(),p=>p.Name,StringComparer.Ordinal),p=>new JProperty(p.Name,Sort(p.Value)))):t is JArray a?new JArray(System.Linq.Enumerable.Select(a,Sort)):t.DeepClone();return Sort(JToken.FromObject(value,JsonSerializer.Create(Settings))).ToString(Formatting.None);}
 public static string Hash(object value){using var sha=SHA256.Create();return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(Canonical(value)))).Replace("-","").ToLowerInvariant();}
 public static string FileHash(string path){using var input=File.OpenRead(path);using var sha=SHA256.Create();return BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant();}
 public static string Id(string id){if(!Guid.TryParseExact(id,"N",out _))throw new CadException("INVALID_ID","A 32-character GUID is required.");return id;}
 public static string LayerName(string name){if(string.IsNullOrWhiteSpace(name)||name.Length>255||System.Linq.Enumerable.Any(name,c=>char.IsControl(c)||"<>/\\\":;?*|=,`".IndexOf(c)>=0))throw new CadException("INVALID_LAYER","Tên layer CAD không hợp lệ.");return name;}
 public static string Name(string name){if(string.IsNullOrWhiteSpace(name)||name.Length>100||System.Linq.Enumerable.Any(name,c=>!char.IsLetterOrDigit(c)&&c!='_'&&c!='-'))throw new CadException("INVALID_NAME","Only letters, digits, _ and - are allowed.");return name;}
 public static void Atomic(string path,object value){Directory.CreateDirectory(System.IO.Path.GetDirectoryName(path)!);string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var file=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None))using(var writer=new StreamWriter(file,new UTF8Encoding(false))){writer.Write(Write(value));writer.Flush();file.Flush(true);}if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
}

